    DECLARE @SQL NVARCHAR(MAX);
    SET @SQL = N'SELECT * FROM ' + QUOTENAME(@TableName) +
               N' WHERE ' + QUOTENAME(@FilterColumn) + N' = @Value';

    EXEC sp_executesql @SQL, N'@Value NVARCHAR(256)', @Value = @FilterValue;
END;

